                                            "subscriptions": "[subscription().subscriptionId]",
                                            "timerange": "Last 12 hours"
                                        }
                                    }
                                }
                            },
                            "runAfter": {
                                "Parse_JSON_-_Get_VIP_Azure_AD_Group_Members": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Foreach"
                        },
                        "HTTP_-_Get_Group_details": {
