                                    }
                                ]
                            }
                        },
                        "Parse_JSON_-_Get_VIP_Azure_AD_Group_Members": {
                            "runAfter": {
                                "HTTP_-_Get_VIP_Azure_AD_Group_Members": [
                                    "Succeeded"
                                ]
                            },
                            "type": "ParseJson",
                            "inputs": {
                                "content": "@body('HTTP_-_Get_VIP_Azure_AD_Group_Members')",
                                "schema": {
