{
    "$schema": "https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
		"comment": "This playbook leverages the Recorded Future API and automatically imports the Actively Communicating C&C Server IPs and C&C DNS Names, as Threat Intelligence Indicators, for Malware C2 detection purposes in Azure Sentinel",
		"author": "Adrian Porcescu, Recorded Future"
	},
	"parameters": {
        "PlaybookName": {
            "defaultValue": "RecordedFuture_C2_Malware_Detection_IndicatorProcessor",
            "type": "string"
        },
        "PlaybookNameBatching": {
            "defaultValue": "RecordedFuture_C2_Malware_Detection_ImportToSentinel",
            "type": "string"
        },
        "BatchName": {
            "defaultValue": "RFDetectC2Malware",
            "type": "string"
        },
        "UserName": {
            "defaultValue": "<username>@<domain>",
            "type": "string"
        }
    },
    "variables": {
        "RecordedFutureConnectionName": "[concat('recordedfuture-', parameters('PlaybookName'))]"
    },
	"resources": [
		{
			"type": "Microsoft.Logic/workflows",
			"apiVersion": "2016-06-01",
			"name": "[parameters('PlaybookName')]",
			"location": "[resourceGroup().location]",
			"dependsOn": [
				"[resourceId('Microsoft.Web/connections', variables('RecordedFutureConnectionName'))]"
			],
			"properties": {
				"definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "actions": {
                        "For_each": {
                            "actions": {
                                "Parse_JSON": {
                                    "inputs": {
                                        "content": "@items('For_each')",
                                        "schema": {
                                            "properties": {
                                                "EvidenceDetails": {
                                                    "properties": {
                                                        "EvidenceDetails": {
                                                            "items": {
                                                                "properties": {
                                                                    "Criticality": {
                                                                        "type": "integer"
                                                                    },
                                                                    "CriticalityLabel": {
                                                                        "type": "string"
                                                                    },
                                                                    "EvidenceString": {
                                                                        "type": "string"
                                                                    },
                                                                    "Rule": {
                                                                        "type": "string"
                                                                    },
                                                                    "Timestamp": {
                                                                        "type": "integer"
                                                                    }
                                                                },
                                                                "required": [
                                                                    "Rule",
                                                                    "EvidenceString",
                                                                    "CriticalityLabel",
                                                                    "Timestamp",
                                                                    "Criticality"
                                                                ],
                                                                "type": "object"
                                                            },
                                                            "type": "array"
                                                        }
                                                    },
                                                    "type": "object"
                                                },
                                                "Name": {
                                                    "type": "string"
                                                },
                                                "Risk": {
                                                    "type": "integer"
                                                },
                                                "riskString": {
                                                    "type": "string"
                                                }
                                            },
                                            "type": "object"
                                        }
                                    },
                                    "runAfter": {},
                                    "type": "ParseJson"
                                },
                                "RecordedFuture_C2_Malware_Detection_ImportToSentinel": {
                                    "inputs": {
                                        "batchName": "[parameters('BatchName')]",
                                        "content": {
                                            "action": "alert",
                                            "additionalInformation": "@{body('Parse_JSON')?['EvidenceDetails']}",
                                            "azureTenantId": "[subscription().tenantId]",
                                            "confidence": "@int(body('Parse_JSON')?['Risk'])",
                                            "description": "Recorded Future - C2 Malware Detection",
                                            "expirationDateTime": "@{addDays(utcNow(),1)}",
                                            "ingestedDateTime": "@{utcNow()}",
                                            "isActive": true,
                                            "networkIPv4": "@{body('Parse_JSON')?['Name']}",
                                            "targetProduct": "Azure Sentinel",
                                            "threatType": "C2",
                                            "tlpLevel": "Amber"
                                        },
                                        "host": {
                                            "triggerName": "Batch_messages",
                                            "workflow": {
                                                "id": "[concat('/subscriptions/', subscription().subscriptionId, '/resourceGroups/', resourceGroup().name, '/providers/Microsoft.Logic/workflows/', parameters('PlaybookNameBatching'))]"
                                            }
                                        }
                                    },
                                    "runAfter": {
                                        "Parse_JSON": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "SendToBatch"
                                }
                            },
                            "foreach": "@body('Recorded_Future_RiskLists_and_SCF_Download')",
                            "runAfter": {
                                "Recorded_Future_RiskLists_and_SCF_Download": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Foreach"
                        },
                        "For_each_2": {
                            "actions": {
                                "Parse_JSON_2": {
                                    "inputs": {
                                        "content": "@items('For_each_2')",
                                        "schema": {
                                            "properties": {
                                                "EvidenceDetails": {
                                                    "properties": {
                                                        "EvidenceDetails": {
                                                            "items": {
                                                                "properties": {
                                                                    "Criticality": {
                                                                        "type": "integer"
                                                                    },
                                                                    "CriticalityLabel": {
                                                                        "type": "string"
                                                                    },
                                                                    "EvidenceString": {
                                                                        "type": "string"
                                                                    },
                                                                    "Rule": {
                                                                        "type": "string"
                                                                    },
                                                                    "Timestamp": {
                                                                        "type": "integer"
                                                                    }
                                                                },
                                                                "required": [
                                                                    "Rule",
                                                                    "EvidenceString",
                                                                    "CriticalityLabel",
                                                                    "Timestamp",
                                                                    "Criticality"
                                                                ],
                                                                "type": "object"
                                                            },
                                                            "type": "array"
                                                        }
                                                    },
                                                    "type": "object"
                                                },
                                                "Name": {
                                                    "type": "string"
                                                },
                                                "Risk": {
                                                    "type": "integer"
                                                },
                                                "riskString": {
                                                    "type": "string"
                                                }
                                            },
                                            "type": "object"
                                        }
                                    },
                                    "runAfter": {},
