                                    "foreach": "@body('Entities_-_Get_Accounts')?['Accounts']",
                                    "actions": {
                                        "Condition_to_check_if_username_is_exists": {
                                            "actions": {
                                                "Condition_to_check_if_user_having_IP_address_or_not": {
                                                    "actions": {
                                                        "For_each_IP_address": {
                                                            "foreach": "@outputs('Get_IP_Address_by_Domain_and_Username_-_Forcepoint_FUID')?['body']?['ipv4_addresses']",
                                                            "actions": {
                                                                "Append_IPaddress_for_each_IP_address": {
                                                                    "runAfter": {
                                                                        "Set_consolidate_variable_if_user_having_IP_address": [
                                                                            "Succeeded"
                                                                        ]
                                                                    },
                                                                    "type": "AppendToArrayVariable",
                                                                    "inputs": {
                                                                        "name": "IPAddress",
                                                                        "value": "@variables('Consolidatevrbl')"
                                                                    },
                                                                    "description": "Append IPaddress for each IP address"
                                                                },
                                                                "Set_consolidate_variable_if_user_having_IP_address": {
                                                                    "runAfter": {},
                                                                    "type": "SetVariable",
                                                                    "inputs": {
                                                                        "name": "Consolidatevrbl",
                                                                        "value": {
                                                                            "IPaddress": "@{items('For_each_IP_address')}",
                                                                            "Usernames": "@{items('Appending_Usernames')?['AadUserId']}"
                                                                        }
                                                                    },
                                                                    "description": "Set consolidate variable if user having IP address"
                                                                }
                                                            },
                                                            "runAfter": {},
                                                            "type": "Foreach"
                                                        }
                                                    },
                                                    "runAfter": {},
                                                    "else": {
                                                        "actions": {
                                                            "Append_to_all_actions_array_if_user_not_has_IP_address": {
                                                                "runAfter": {
                                                                    "Set_consolidate_variable_if_user_not_has_IP_address": [
                                                                        "Succeeded"
                                                                    ]
                                                                },
                                                                "type": "AppendToArrayVariable",
                                                                "inputs": {
                                                                    "name": "Arrayforallactions",
                                                                    "value": "@variables('Consolidatevrbl')"
                                                                },
                                                                "description": "Append to all actions array if user not has IP address"
                                                            },
                                                            "Set_consolidate_variable_if_user_not_has_IP_address": {
                                                                "runAfter": {},
                                                                "type": "SetVariable",
                                                                "inputs": {
                                                                    "name": "Consolidatevrbl",
                                                                    "value": {
                                                                        "Action": "@{items('Appending_Usernames')} does not have IP address",
                                                                        "IPAddres": "",
                                                                        "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}"
                                                                    }
                                                                },
                                                                "description": "Set consolidate variable if user not has IP address"
                                                            },
                                                            "Set_terminate_variable_if_user_not_has_IP_address": {
                                                                "runAfter": {
                                                                    "Append_to_all_actions_array_if_user_not_has_IP_address": [
                                                                        "Succeeded"
                                                                    ]
                                                                },
                                                                "type": "SetVariable",
                                                                "inputs": {
                                                                    "name": "Terminate",
                                                                    "value": "APIError"
                                                                },
                                                                "description": "Set terminate variable if user not has IP address"
                                                            }
                                                        }
                                                    },
                                                    "expression": {
                                                        "and": [
                                                            {
                                                                "greater": [
                                                                    "@length(outputs('Get_IP_Address_by_Domain_and_Username_-_Forcepoint_FUID')?['body']?['ipv4_addresses'])",
                                                                    0
                                                                ]
                                                            }
                                                        ]
                                                    },
                                                    "type": "If",
                                                    "description": "Condition to check if user having IP address or not"
                                                }
                                            },
                                            "runAfter": {
                                                "Get_IP_Address_by_Domain_and_Username_-_Forcepoint_FUID": [
                                                    "Succeeded",
                                                    "TimedOut",
                                                    "Skipped",
                                                    "Failed"
                                                ]
                                            },
                                            "else": {
                                                "actions": {
                                                    "Append_to_array_variable_of_all_actions_array": {
                                                        "runAfter": {
                                                            "Set_variable_to_consolidate_variable": [
                                                                "Succeeded"
                                                            ]
                                                        },
                                                        "type": "AppendToArrayVariable",
                                                        "inputs": {
                                                            "name": "Arrayforallactions",
                                                            "value": "@variables('Consolidatevrbl')"
                                                        }
                                                    },
                                                    "Set_terminate_variable_if_username_is_not_exist": {
                                                        "runAfter": {
                                                            "Append_to_array_variable_of_all_actions_array": [
                                                                "Succeeded"
                                                            ]
                                                        },
                                                        "type": "SetVariable",
                                                        "inputs": {
                                                            "name": "Terminate",
                                                            "value": "APIError"
                                                        },
                                                        "description": "Set terminate variable if username is not exist"
                                                    },
                                                    "Set_variable_to_consolidate_variable": {
                                                        "runAfter": {},
                                                        "type": "SetVariable",
                                                        "inputs": {
                                                            "name": "Consolidatevrbl",
                                                            "value": {
                                                                "Action": "@{items('Appending_Usernames')} does not exist",
                                                                "IPAddres": "",
                                                                "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}"
                                                            }
                                                        }
                                                    }
                                                }
                                            },
                                            "expression": {
                                                "and": [
                                                    {
                                                        "equals": [
                                                            "@outputs('Get_IP_Address_by_Domain_and_Username_-_Forcepoint_FUID')?['statusCode']",
                                                            200
                                                        ]
                                                    }
                                                ]
                                            },
                                            "type": "If",
                                            "description": "Condition to check if username is exists"
                                        },
                                        "Get_IP_Address_by_Domain_and_Username_-_Forcepoint_FUID": {
                                            "runAfter": {
                                                "Seperator": [
                                                    "Succeeded"
                                                ]
                                            },
                                            "type": "ApiConnection",
                                            "inputs": {
                                                "headers": {
                                                    "Accept": "application/json",
                                                    "Content-Type": "application/json"
                                                },
                                                "host": {
                                                    "connection": {
                                                        "name": "@parameters('$connections')['ForcepointFUIDConnector']['connectionId']"
                                                    }
                                                },
                                                "method": "get",
                                                "path": "/api/uid/@{encodeURIComponent(variables('FUID Version'))}/user/ntlm-identity/@{encodeURIComponent(split(last(split(items('Appending_Usernames')?['AadUserId'],'@')),'.')[0],outputs('Seperator'),split(items('Appending_Usernames')?['AadUserId'],'@')[0])}"
                                            }
                                        },
                                        "Seperator": {
                                            "runAfter": {},
                                            "type": "Compose",
                                            "inputs": "\\"
                                        }
                                    },
                                    "runAfter": {},
                                    "type": "Foreach"
                                },
                                "Check_Login_Status": {
                                    "runAfter": {
                                        "Login": [
                                            "Succeeded",
                                            "Failed",
                                            "Skipped",
                                            "TimedOut"
                                        ]
                                    },
                                    "cases": {
                                        "200_Success_OK": {
                                            "case": 200,
                                            "actions": {
                                                "Condition_to_check_if_IP_list_is_exist_or_not": {
                                                    "actions": {
                                                        "Add_IP_Address_into_IP_List": {
                                                            "runAfter": {
                                                                "Looping_IP_Address": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "body": {
                                                                    "ip": "@variables('IP Address')"
                                                                },
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "post",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/ip_list/@{encodeURIComponent(last(split(body('Get_IP_List_Element')?['result']?[0]?['href'],'/')))}/ip_address_list"
                                                            }
                                                        },
                                                        "Condition_to_check_if_needs_to_be_terminated": {
                                                            "actions": {
                                                                "Terminate_the_playbook_if_API_issue_occurred": {
                                                                    "runAfter": {},
                                                                    "type": "Terminate",
                                                                    "inputs": {
                                                                        "runError": {
                                                                            "message": "Having API issue in playbook"
                                                                        },
                                                                        "runStatus": "Failed"
                                                                    },
                                                                    "description": "Terminate the playbook if API issue occurred"
                                                                }
                                                            },
                                                            "runAfter": {
                                                                "Create_HTML_table_for_Add_comment_to_incident": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "else": {
                                                                "actions": {
                                                                    "Add_comment_to_incident_(V3)": {
                                                                        "runAfter": {},
                                                                        "type": "ApiConnection",
                                                                        "inputs": {
                                                                            "body": {
                                                                                "incidentArmId": "@triggerBody()?['object']?['id']",
                                                                                "message": "<p>@{outputs('Forcepoint_Logo')}<strong>Forcepoint NGFW Block IP Address by Username</strong><br>\n<br>\nThe below Username are found to be malicious and playbook taken action against to that Username IPs.<br>\n<br>\n@{body('Create_HTML_table_for_Add_comment_to_incident')}</p>"
                                                                            },
                                                                            "host": {
                                                                                "connection": {
                                                                                    "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                                                                }
                                                                            },
                                                                            "method": "post",
                                                                            "path": "/Incidents/Comment"
                                                                        }
                                                                    },
                                                                    "Update_incident": {
                                                                        "runAfter": {
                                                                            "Add_comment_to_incident_(V3)": [
                                                                                "Succeeded"
                                                                            ]
                                                                        },
                                                                        "type": "ApiConnection",
                                                                        "inputs": {
                                                                            "body": {
                                                                                "classification": {
                                                                                    "ClassificationAndReason": "TruePositive - SuspiciousActivity"
                                                                                },
                                                                                "incidentArmId": "@triggerBody()?['object']?['id']",
                                                                                "status": "Closed"
                                                                            },
                                                                            "host": {
                                                                                "connection": {
                                                                                    "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                                                                }
                                                                            },
                                                                            "method": "put",
                                                                            "path": "/Incidents"
                                                                        }
                                                                    }
                                                                }
                                                            },
                                                            "expression": {
                                                                "and": [
                                                                    {
                                                                        "equals": [
                                                                            "@variables('Terminate')",
                                                                            "APIError"
                                                                        ]
                                                                    }
                                                                ]
                                                            },
                                                            "type": "If",
                                                            "description": "Condition to check if needs to be terminated"
                                                        },
                                                        "Create_HTML_table_for_Add_comment_to_incident": {
                                                            "runAfter": {
                                                                "Add_IP_Address_into_IP_List": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "Table",
                                                            "inputs": {
                                                                "columns": [
                                                                    {
                                                                        "header": "User-ID",
                                                                        "value": "@item()?['Username']"
                                                                    },
                                                                    {
                                                                        "header": "IP-Address",
                                                                        "value": "@item()?['IPAddres']"
                                                                    },
                                                                    {
                                                                        "header": "IP-List-Name",
                                                                        "value": "@variables('IP list name')"
                                                                    },
                                                                    {
                                                                        "header": "IP-Status",
                                                                        "value": "@item()?['IPStatus']"
                                                                    },
                                                                    {
                                                                        "header": "Action-Taken",
                                                                        "value": "@item()?['Action']"
                                                                    }
                                                                ],
                                                                "format": "HTML",
                                                                "from": "@variables('Arrayforallactions')"
                                                            },
                                                            "description": "Creating a HTML table from all actions taken by IP address"
                                                        },
                                                        "Get_IP_address": {
                                                            "runAfter": {},
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "get",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/ip_list/@{encodeURIComponent(last(split(body('Get_IP_List_Element')?['result']?[0]?['href'],'/')))}/ip_address_list"
                                                            }
                                                        },
                                                        "Looping_IP_Address": {
                                                            "foreach": "@variables('IPAddress')",
                                                            "actions": {
                                                                "Check_the_result_length_from_filter_output": {
                                                                    "actions": {
                                                                        "Append_to_array_of_all_actions": {
                                                                            "runAfter": {
                                                                                "Set_variable_to_consolidate_variable_set": [
                                                                                    "Succeeded"
                                                                                ]
                                                                            },
                                                                            "type": "AppendToArrayVariable",
                                                                            "inputs": {
                                                                                "name": "Arrayforallactions",
                                                                                "value": "@variables('Consolidatevrbl')"
                                                                            }
                                                                        },
                                                                        "Set_variable_to_consolidate_variable_set": {
                                                                            "runAfter": {},
                                                                            "type": "SetVariable",
                                                                            "inputs": {
                                                                                "name": "Consolidatevrbl",
                                                                                "value": {
                                                                                    "Action": "Already blocked",
                                                                                    "IPAddres": "@{items('Looping_IP_Address')['IPaddress']}",
                                                                                    "IPStatus": "Blocked",
                                                                                    "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}",
                                                                                    "Username": "@{items('Looping_IP_Address')['Usernames']}"
                                                                                }
                                                                            }
                                                                        }
                                                                    },
                                                                    "runAfter": {},
                                                                    "else": {
                                                                        "actions": {
                                                                            "Append_to_array_variable_to_Not_exit_IP_address": {
                                                                                "runAfter": {},
                                                                                "type": "AppendToArrayVariable",
                                                                                "inputs": {
                                                                                    "name": "IP Address",
                                                                                    "value": "@items('Looping_IP_Address')['IPaddress']"
                                                                                },
                                                                                "description": "Append to array variable to Not exit IP address"
                                                                            },
                                                                            "Append_to_array_variable_to_array_for_actions": {
                                                                                "runAfter": {
                                                                                    "Set_variable_for_consolidate_variable": [
                                                                                        "Succeeded"
                                                                                    ]
                                                                                },
                                                                                "type": "AppendToArrayVariable",
                                                                                "inputs": {
                                                                                    "name": "Arrayforallactions",
                                                                                    "value": "@variables('Consolidatevrbl')"
                                                                                },
                                                                                "description": "Append to array variable to array for actions"
                                                                            },
                                                                            "Set_variable_for_consolidate_variable": {
                                                                                "runAfter": {
                                                                                    "Append_to_array_variable_to_Not_exit_IP_address": [
                                                                                        "Succeeded"
                                                                                    ]
                                                                                },
                                                                                "type": "SetVariable",
                                                                                "inputs": {
                                                                                    "name": "Consolidatevrbl",
                                                                                    "value": {
                                                                                        "Action": "Blocked by playbook",
                                                                                        "IPAddres": "@{items('Looping_IP_Address')['IPaddress']}",
                                                                                        "IPStatus": "Blocked",
                                                                                        "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}",
                                                                                        "Username": "@{items('Looping_IP_Address')['Usernames']}"
                                                                                    }
                                                                                },
                                                                                "description": "Set variable for consolidate variable"
                                                                            }
                                                                        }
                                                                    },
                                                                    "expression": {
                                                                        "and": [
                                                                            {
                                                                                "contains": [
                                                                                    "@body('Get_IP_address')?['ip']",
                                                                                    "@items('Looping_IP_Address')['IPaddress']"
                                                                                ]
                                                                            }
                                                                        ]
                                                                    },
                                                                    "type": "If",
                                                                    "description": "We will check for the result output is empty or exist in the policy rule. If result output is empty ,then there is no policy based on IP Address. And If result ouput is having some information related to IP Address then there is a policy with respect to IP"
                                                                }
                                                            },
                                                            "runAfter": {
                                                                "Set_variable_for_IP_list_array_from_SMC_IP_address": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "Foreach",
                                                            "description": "Here we are looping each IP Address and check whether it is blocked or not "
                                                        },
                                                        "Set_variable_for_IP_list_array_from_SMC_IP_address": {
                                                            "runAfter": {
                                                                "Get_IP_address": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "SetVariable",
                                                            "inputs": {
                                                                "name": "IP Address",
                                                                "value": "@body('Get_IP_address')?['ip']"
                                                            },
                                                            "description": "Set variable for IP list array from SMC IP address"
                                                        }
                                                    },
                                                    "runAfter": {
                                                        "Get_IP_List_Element": [
                                                            "Succeeded",
                                                            "TimedOut",
                                                            "Skipped",
                                                            "Failed"
                                                        ]
                                                    },
                                                    "else": {
                                                        "actions": {
                                                            "Terminate": {
                                                                "runAfter": {},
                                                                "type": "Terminate",
                                                                "inputs": {
                                                                    "runError": {
                                                                        "message": "@{variables('IP list name')} does not exist in SMC. Please create IP list prior to deploy the playbook."
                                                                    },
                                                                    "runStatus": "Failed"

